CREATE TABLE cleaned_measurements AS
SELECT *
FROM measurements
WHERE cognitive_score < (
    SELECT AVG(cognitive_score) + 2 * (SELECT sqrt((SUM(cognitive_score * cognitive_score) - (SUM(cognitive_score) * SUM(cognitive_score) / COUNT(*))) / (COUNT(*) - 1)) FROM measurements)
) AND cognitive_score > (
    SELECT AVG(cognitive_score) - 2 * (SELECT sqrt((SUM(cognitive_score * cognitive_score) - (SUM(cognitive_score) * SUM(cognitive_score) / COUNT(*))) / (COUNT(*) - 1)) FROM measurements)
);

